-- Additive and independent of login accounts, users and their historical publications.
CREATE TABLE IF NOT EXISTS department_teachers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,grade TEXT NOT NULL DEFAULT '',specialty TEXT NOT NULL DEFAULT '',levels_json TEXT NOT NULL DEFAULT '[]',tracks_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','unavailable','retired')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS department_teacher_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,teacher_id BIGINT NOT NULL REFERENCES department_teachers(id) DEFERRABLE INITIALLY IMMEDIATE,actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY IMMEDIATE,previous_json TEXT NOT NULL,changed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_department_teachers_name ON department_teachers(name);
